// Review report for EFPS hardware-token resolution.
//
//   npx tsx scripts/thirdParty/efps-token-report.ts [--check]
//
// Writes research/userbenchmark/efps-token-resolution.md — the human-readable
// account of which UserBenchmark EFPS shorthand tokens resolved to SpecSmith
// canonical ids, which did not, and exactly why each blocked one was refused.
//
// The blocked list is the point. A resolution layer that only reports its
// successes hides the decisions that actually matter: every token it declined
// is a judgement someone should be able to disagree with, so each one is
// printed with its reason, its occurrence count, and the catalog ids a careless
// matcher would have reached for instead.
//
// Deterministic: no clock, no counters. The report is a pure function of the
// store and the map, so `--check` can assert it is current in CI.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { getEfpsStoreSummary, getEfpsStore } from '../../src/lib/thirdParty/efpsStore';
import { EFPS_HARDWARE_MAP_VERSION, declaredCanonicalIds } from '../../src/lib/thirdParty/efpsHardwareMap';
import type { EfpsTokenCoverage } from '../../src/lib/thirdParty/efpsStore';

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.join(here, '..', '..');
const outFile = path.join(repoRoot, 'research', 'userbenchmark', 'efps-token-resolution.md');

function table(rows: readonly EfpsTokenCoverage[]): string {
  const lines = [
    '| Token | Datapoints | Outcome | Canonical id | Reason |',
    '| --- | ---: | --- | --- | --- |',
  ];
  for (const t of rows) {
    const outcome = t.resolved ? 'resolved' : (t.blockReason ?? 'blocked');
    const id = t.canonicalId ?? '—';
    const near = t.candidates && t.candidates.length > 0 ? ` **Near-misses refused: ${t.candidates.join(', ')}.**` : '';
    const reason = t.resolved ? 'Explicit reviewed alias.' : `${t.detail ?? ''}${near}`;
    lines.push(`| \`${t.token}\` | ${t.occurrences} | ${outcome} | ${id} | ${reason.replace(/\|/g, '\\|')} |`);
  }
  return lines.join('\n');
}

export function buildReport(): string {
  const s = getEfpsStoreSummary();
  const store = getEfpsStore();
  const unresolved = [...s.gpuTokens, ...s.cpuTokens].filter((t) => !t.resolved);
  const resolvedCpu = declaredCanonicalIds('cpu');
  const resolvedGpu = declaredCanonicalIds('gpu');

  return `# EFPS hardware-token resolution — review report

Generated by \`scripts/thirdParty/efps-token-report.ts\`. Do not edit by hand.

Token map version: **${EFPS_HARDWARE_MAP_VERSION}**
Store schema version: **${store.schemaVersion}**
Store content hash: \`${store.contentSha256}\`

## Summary

| | GPU | CPU |
| --- | ---: | ---: |
| Unique tokens in the accepted corpus | ${s.gpuTokens.length} | ${s.cpuTokens.length} |
| Resolved to a canonical id | ${s.gpuTokens.filter((t) => t.resolved).length} | ${s.cpuTokens.filter((t) => t.resolved).length} |
| Unresolved / blocked | ${s.gpuTokens.filter((t) => !t.resolved).length} | ${s.cpuTokens.filter((t) => !t.resolved).length} |

- EFPS records: **${s.total}** (${s.direct} direct, ${s.comparison} comparison) across ${s.games.length} games
- Individual FPS datapoints: **${s.datapoints}**
- Datapoints with BOTH hardware sides resolved: **${s.joinableDatapoints}**
- Records marked \`hardwareJoinable\`: **${s.hardwareJoinable}**
- Records still blocked: **${s.total - s.hardwareJoinable}**

A record is joinable only when every one of its datapoints resolved both its
GPU and its CPU token. No EFPS GPU token has a SpecSmith catalog counterpart —
the corpus is 2016-2019 hardware and the catalog starts at RTX 3050 / RX 6400 —
so no record is joinable today, including the ${s.cpuTokens.filter((t) => t.resolved).reduce((n, t) => n + t.occurrences, 0)} datapoints whose CPU did resolve.

## Resolved mappings

${resolvedGpu.length + resolvedCpu.length === 0 ? '_None._' : ''}${[...resolvedGpu.map((d) => ['GPU', d] as const), ...resolvedCpu.map((d) => ['CPU', d] as const)]
    .map(([kind, d]) => `- **${kind} \`${d.token}\`** → \`${d.canonicalId}\` (${d.denotes})`)
    .join('\n')}

Every resolved id is verified against the shipping catalog at ingestion time:
the ingest script refuses to write a store containing an id \`gpus.json\` /
\`cpus.json\` does not have, or one whose catalog entry is a different part from
the one the mapping claims to denote.

## Unresolved and ambiguous tokens — ${unresolved.length} needing review

These are blocked with null canonical ids. Nothing downstream may join them.

### GPU tokens

${table(s.gpuTokens.filter((t) => !t.resolved))}

### CPU tokens

${table(s.cpuTokens.filter((t) => !t.resolved))}

## What would change these outcomes

Almost every block above is \`not-in-catalog\`: the part is identified without
ambiguity, SpecSmith simply has no entry for it. Those resolve the day the
corresponding part is added to \`gpus.json\` / \`cpus.json\` and a reviewed alias
is added to \`efpsHardwareMap.ts\` — not before, and never automatically.

The near-miss columns are the reason this is a hand-written table rather than a
similarity function. Matching on digits alone against the real catalog maps the
AMD RX 580 onto an Intel Arc A580, the AMD Ryzen 5 2600 onto an Intel i5-12600K,
and the Intel i5-9600K onto an AMD Ryzen 5 9600X. Each is a different vendor,
and in several cases a different decade.
`;
}

function main(argv: string[]): void {
  const report = buildReport();
  const existing = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf-8') : null;

  if (argv.includes('--check')) {
    if (existing !== report) {
      console.error(`${path.relative(repoRoot, outFile)} is out of date. Re-run without --check.`);
      process.exitCode = 1;
      return;
    }
    console.log('Token report is up to date.');
    return;
  }

  fs.writeFileSync(outFile, report);
  console.log(`${existing === report ? 'Unchanged' : 'Wrote'}: ${path.relative(repoRoot, outFile)}`);
}

const invokedDirectly = process.argv[1] !== undefined && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) main(process.argv.slice(2));
